package dev.aegisac;
import java.nio.file.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;import java.util.logging.Logger;import java.nio.charset.StandardCharsets;
/** Persistent bounded confirmed-event ledger; one coalesced writer, no per-packet I/O. */
final class ConfirmedHistory implements AutoCloseable {
 record Entry(long time,UUID player,String name,String type,String reason){}
 private static final int LIMIT=512;private final Deque<Entry> entries=new ArrayDeque<>();private final Path path;private final Logger log;private final Object writeLock=new Object();private long version;
 private final AtomicBoolean scheduled=new AtomicBoolean();private final ExecutorService writer=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"AegisAC-History");t.setDaemon(true);return t;});
 ConfirmedHistory(Path path,Logger log){this.path=path;this.log=log;load();}
 synchronized void append(UUID player,String name,String type,String reason){if(player==null)return;entries.addLast(new Entry(System.currentTimeMillis(),player,clean(name),clean(type),clean(reason)));while(entries.size()>LIMIT)entries.removeFirst();version++;schedule();}
 synchronized List<Entry> latest(UUID player,int limit){List<Entry> out=new ArrayList<>();Iterator<Entry> it=entries.descendingIterator();while(it.hasNext()&&out.size()<Math.min(50,Math.max(1,limit))){Entry e=it.next();if(player==null||e.player.equals(player))out.add(e);}return List.copyOf(out);}
 synchronized int size(){return entries.size();}
 synchronized void clear(UUID id){entries.removeIf(e->e.player.equals(id));version++;schedule();}
 private static String clean(String value){return value==null?"":value.replaceAll("[\\p{Cntrl}§]","").substring(0,Math.min(240,value.replaceAll("[\\p{Cntrl}§]","").length()));}
 private void schedule(){if(scheduled.compareAndSet(false,true))try{writer.execute(this::flush);}catch(RejectedExecutionException closed){scheduled.set(false);}}
 private void flush(){try{for(;;){List<Entry> snapshot;long current;synchronized(this){snapshot=List.copyOf(entries);current=version;}write(snapshot);synchronized(this){if(version==current){scheduled.set(false);return;}}}}catch(IOException failure){scheduled.set(false);log.warning("Confirmed history storage unavailable: "+failure.getClass().getSimpleName());}}
 private static String encode(String v){return Base64.getEncoder().encodeToString(v.getBytes(StandardCharsets.UTF_8));}private static String decode(String v){return new String(Base64.getDecoder().decode(v),StandardCharsets.UTF_8);}
 private void write(List<Entry> snapshot)throws IOException{synchronized(writeLock){Properties p=new Properties();int i=0;for(Entry e:snapshot)p.setProperty("event."+(i++),e.time+"|"+e.player+"|"+encode(e.name)+"|"+encode(e.type)+"|"+encode(e.reason));Path tmp=path.resolveSibling(path.getFileName()+".tmp");Files.createDirectories(path.getParent());try(OutputStream out=Files.newOutputStream(tmp)){p.store(out,"AegisAC confirmed events; bounded to 512");}try{Files.move(tmp,path,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException unsupported){Files.move(tmp,path,StandardCopyOption.REPLACE_EXISTING);}}}
 private void load(){if(!Files.exists(path))return;try(InputStream in=Files.newInputStream(path)){Properties p=new Properties();p.load(in);for(int i=0;i<LIMIT;i++){String row=p.getProperty("event."+i);if(row==null)continue;try{String[] a=row.split("\\|",-1);if(a.length==5)entries.addLast(new Entry(Long.parseLong(a[0]),UUID.fromString(a[1]),decode(a[2]),decode(a[3]),decode(a[4])));}catch(RuntimeException invalid){log.warning("Skipped invalid confirmed history entry");}}}catch(IOException|IllegalArgumentException failure){log.warning("Confirmed history could not be read: "+failure.getClass().getSimpleName());}}
 public void close(){writer.shutdown();try{writer.awaitTermination(2,TimeUnit.SECONDS);List<Entry> snapshot;synchronized(this){snapshot=List.copyOf(entries);}write(snapshot);}catch(InterruptedException interrupted){Thread.currentThread().interrupt();}catch(IOException failure){log.warning("Confirmed history could not be saved: "+failure.getClass().getSimpleName());}}
}
